  const field = (label,name,value='',type='text',hint='') => `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" step="any"':''} ${name==='title'?'required':''}><small>${hint}</small></label>`;
