    const metrics = seller ? [metric('عرضه‌های فعال',offers.filter(x=>x.status==='active').length,'فقط گالری آوای طلا','layers','offers'),metric('موجودی قابل تخصیص',offers.reduce((s,o)=>s+o.stock-o.reserved,0),'پس از کسر رزرو','box','offers'),metric('سفارش‌های در جریان',orders.filter(x=>x.status!=='delivered').length,'نیازمند تأمین و ارسال','receipt','orders'),metric('منتظر تأمین',orders.filter(x=>!x.supply).length,'اطلاعات مشتری محدود است','truck','orders')] : finance ? [metric('تراکنش نامشخص',CV.transfers.filter(x=>x.status==='unknown').length,'نیازمند استعلام و تطبیق','activity','operations'),metric('برداشت در انتظار',1,'بررسی مستقل از سفارش','wallet','finance'),metric('استرداد در جریان',1,'بدون تأیید موفقیت دستی','swap','finance'),metric('مدل فروش پیش‌نویس',2,'فعال‌سازی پس از قرارداد','card','sale-methods')] : [metric('فروشگاه‌های فعال',CV.stores.filter(x=>x.active).length,'از ۴ فروشگاه نمونه','store','stores'),metric('محصول منتظر بررسی',CV.products.filter(x=>x.status==='pending').length,'در صف انتشار محتوا','box','products'),metric('سفارش‌های در جریان',orders.filter(x=>x.status!=='delivered').length,'از تأمین تا تحویل','receipt','orders'),metric('پرونده‌های باز',cases.filter(x=>x.status!=='closed').length,'نیازمند اقدام همکاران','support','support')];
    const queue = (seller?[['orders','تأمین سفارش جدید','فقط اقلام فروشگاه شما',orders.filter(x=>!x.supply).length],['offers','عرضه منتظر بررسی','قیمت و موجودی را مرور کنید',offers.filter(x=>x.status==='pending').length],['settlements','صورتحساب فروشگاه','گردش و تخصیص اقلام',1]]:finance?[['operations','تطبیق انتقال نامشخص','اجرای مجدد تا تعیین تکلیف مسدود',2],['finance','درخواست برداشت','بررسی منبع و مانده مسدود',1],['gold-policies','تکمیل سیاست طلا','CHQ-03 · فرمول هنوز باز',1]]:[['support','رسیدگی به پرونده‌ها','عدم تأمین و کسری مقدار',cases.filter(x=>x.status!=='closed').length],['products','بررسی محتوای محصول','انتشار مستقل از تغییر قیمت',2],['operations','پیگیری اعلان ناموفق','وضعیت کانال نمونه',1],['operations','تراکنش نامشخص','شاهد قطعی لازم است',2]]).filter(x=>allowed(x[0]));
